function db(){static $d;if(!$d){$d=new PDO('sqlite:'.DB_FILE);$d->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$d->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);}return $d;}
