function esc($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function jsonout($x){header('Content-Type: application/json');echo json_encode($x);exit;}
function workplace(){return db()->query('SELECT * FROM workplaces ORDER BY id LIMIT 1')->fetch();}
function dist($a,$b,$c,$d){$R=6371000;$p=pi()/180;$x=($d-$b)*$p*cos(($a+$c)/2*$p);$y=($c-$a)*$p;return sqrt($x*$x+$y*$y)*$R;}
function today(){return date('Y-m-d');}
function attendance($uid){$s=db()->prepare('SELECT * FROM attendances WHERE user_id=? AND date=?');$s->execute([$uid,today()]);return $s->fetch();}
