function manager(){need('manager');$d=db();$users=$d->query("SELECT u.*,l.latitude,l.longitude,l.status,l.recorded_at FROM users u LEFT JOIN (SELECT l1.* FROM locations l1 JOIN (SELECT user_id,MAX(id) mid FROM locations GROUP BY user_id) x ON x.mid=l1.id) l ON l.user_id=u.id WHERE u.role='employee' AND u.active=1 ORDER BY u.name")->fetchAll();$today=$d->prepare("SELECT COUNT(*) n FROM attendances WHERE date=? AND punch_in IS NOT NULL");$today->execute([today()]);$present=$today->fetch()['n'];$out=$d->prepare("SELECT COUNT(*) n FROM locations WHERE id IN (SELECT MAX(id) FROM locations GROUP BY user_id) AND status='outside'");$out->execute();$outside=$out->fetch()['n'];$ot=$d->prepare("SELECT COALESCE(SUM(overtime_minutes),0) n FROM attendances WHERE date=?");$ot->execute([today()]);$otm=$ot->fetch()['n'];$pending=$d->query("SELECT COUNT(*) n FROM leave_requests WHERE status='pending'")->fetch()['n'];pageHeader('Manager Command Center');?><div class="hero"><div><div class="eyebrow">MANAGER COMMAND CENTER</div><h1>Live workforce visibility</h1><p>Monitor attendance, location, leave and overtime from one dashboard.</p></div><span class="live">● LIVE</span></div><section class="stats"><div class="stat"><span>On shift</span><b><?=$present?></b><small>employees punched in</small></div><div class="stat"><span>Outside geofence</span><b><?=$outside?></b><small>latest location status</small></div><div class="stat"><span>Overtime today</span><b><?=number_format($otm/60,1)?>h</b><small>total overtime</small></div><div class="stat"><span>Leave approvals</span><b><?=$pending?></b><small>pending requests</small></div></section><section class="grid2"><div class="card"><div class="sectionhead"><div><h2>Live employee map</h2><p class="muted">Photo pins show the latest reported location.</p></div><button class="ghost" onclick="loadDashboard()">↻ Refresh</button></div><div id="map"></div><div class="mapfallback" id="mapfallback">Loading live map…</div></div><div class="card"><div class="sectionhead"><h2>Alerts</h2><span class="badge" id="alertCount">0</span></div><div id="alerts" class="list"></div></div></section><section class="card"><div class="sectionhead"><h2>Workforce status</h2><a class="ghost" href="/?page=employees">Manage employees →</a></div><div class="tablewrap"><table><thead><tr><th>Employee</th><th>Status</th><th>Last location</th><th>Reported</th><th>Overtime</th></tr></thead><tbody id="employeeRows"><?php foreach($users as $x):?><tr><td><div class="person"><img src="<?=esc($x['photo']?:'assets/avatar-default.svg')?>"><div><b><?=esc($x['name'])?></b><small><?=esc($x['department'])?></small></div></div></td><td><span class="pill <?=esc($x['status']?:'offline')?>"><?=esc(ucwords(str_replace('_',' ',$x['status']?:'Offline')))?></span></td><td><?=isset($x['latitude'])?esc(number_format($x['latitude'],5).', '.number_format($x['longitude'],5)):'—'?></td><td><?=esc($x['recorded_at']?:'—')?></td><td>—</td></tr><?php endforeach;?></tbody></table></div></section><section class="card"><div class="sectionhead"><h2>Leave approvals</h2><a class="ghost" href="/?page=leaveadmin">Open requests →</a></div><div id="leaveMini" class="list"></div></section><script>
let map,markers={};function initMap(){if(!window.L){document.getElementById('mapfallback').textContent='Map library unavailable. Live status table remains active.';return;}map=L.map('map').setView([17.3850,78.4867],14);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);L.circle([17.3850,78.4867],{radius:250}).addTo(map);loadDashboard();}async function loadDashboard(){try{let r=await fetch('/?api=dashboard'),d=await r.json();document.getElementById('alertCount').textContent=d.alerts.length;document.getElementById('alerts').innerHTML=d.alerts.length?d.alerts.map(a=>`<div class="alert ${a.type}"><b>${a.title}</b><span>${a.message}</span></div>`).join(''):'<div class="empty">No active alerts. Workforce looks healthy.</div>';document.getElementById('leaveMini').innerHTML=d.leaves.length?d.leaves.map(x=>`<div class="leaveitem"><div><b>${x.name}</b><span>${x.type} · ${x.start_date} → ${x.end_date}</span></div><a class="ghost" href="/?page=leaveadmin">Review</a></div>`).join(''):'<div class="empty">No pending leave requests.</div>';if(map){d.employees.forEach(e=>{if(!e.latitude)return;let icon=L.divIcon({className:'photo-pin',html:`<img src="${e.photo||'assets/avatar-default.svg'}"><i></i>`,iconSize:[52,52],iconAnchor:[26,50]});if(markers[e.id])markers[e.id].setLatLng([e.latitude,e.longitude]).setIcon(icon).bindPopup(`<b>${e.name}</b><br>${e.status}<br>${e.latitude.toFixed(5)}, ${e.longitude.toFixed(5)}`);else markers[e.id]=L.marker([e.latitude,e.longitude],{icon}).addTo(map).bindPopup(`<b>${e.name}</b><br>${e.status}`);});} }catch(e){console.error(e)}}window.addEventListener('load',()=>{try{initMap()}catch(e){document.getElementById('mapfallback').textContent='Map could not initialize.'}});setInterval(loadDashboard,5000);</script><?php footer();}
function employee(){ $u=need('employee');$w=workplace();$a=attendance($u['id']) ?: [];$loc=db()->prepare('SELECT * FROM locations WHERE user_id=? ORDER BY id DESC LIMIT 1');$loc->execute([$u['id']]);$l=$loc->fetch();$not=db()->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 5');$not->execute([$u['id']]);$ns=$not->fetchAll();pageHeader('Employee Dashboard');?><div class="hero"><div><div class="eyebrow">EMPLOYEE WORKSPACE</div><h1>Good work, <?=esc(explode(' ',$u['name'])[0])?>.</h1><p>Your attendance, location and shift status are tracked automatically.</p></div><span class="live">● GPS READY</span></div><section class="stats"><div class="stat"><span>Today</span><b id="attStatus"><?=esc(ucwords(str_replace('_',' ',$a['status']??'Not started')))?></b><small>attendance status</small></div><div class="stat"><span>Punch in</span><b><?=esc(($a['punch_in'] ?? null) ? date('h:i A',strtotime($a['punch_in'])):'—')?></b><small>automatic when inside</small></div><div class="stat"><span>Overtime</span><b><?=number_format(($a['overtime_minutes']??0)/60,1)?>h</b><small>calculated at checkout</small></div><div class="stat"><span>Geofence</span><b id="geoStatus"><?=esc(ucwords(str_replace('_',' ',$l['status']??'Unknown')))?></b><small><?=$w['radius']?>m radius</small></div></section><section class="grid2"><div class="card"><div class="sectionhead"><div><h2>Automatic location monitoring</h2><p class="muted">Allow browser GPS. The system decides inside/outside automatically.</p></div><span class="pill online">GPS</span></div><div class="gpsbox"><div class="radar">⌖</div><div><b id="gpsText">Waiting for location permission…</b><span id="coords">No coordinates reported yet.</span></div></div><div class="actions"><button type="button" id="btnGPS" class="primary">Enable automatic GPS</button><button type="button" id="btnInside" class="secondary">Simulate Inside</button><button type="button" id="btnOutside" class="secondary">Simulate Outside</button><button type="button" id="btnRemote" class="secondary">Simulate Approved Remote</button></div><p class="hint">Demo controls are included so judges can see the geofence logic even on a laptop without moving physically.</p></div><div class="card"><div class="sectionhead"><div><h2>Identity photo</h2><p class="muted">Capture/update your photo. Managers see this photo with your live location.</p></div><button type="button" id="btnCamera" class="primary">📸 Take photo</button></div><div class="photoarea"><img id="myPhoto" class="bigphoto" src="<?=esc($u['photo']?:'assets/avatar-default.svg')?>"><div id="cameraBox" style="display:none"><video id="video" autoplay playsinline muted></video><div class="actions"><button type="button" id="btnCapture" class="primary">Capture</button><button type="button" id="btnCancelCamera" class="secondary">Cancel</button></div></div></div><div id="photoMsg" class="hint"></div></div></section><section class="card"><div class="sectionhead"><h2>Recent notifications</h2><a class="ghost" href="/?page=leave">Manage leave →</a></div><div class="list"><?=count($ns)?implode('',array_map(fn($n)=>'<div class="alert '.$n['type'].'"><b>'.esc($n['title']).'</b><span>'.esc($n['message']).'</span></div>',$ns)):'<div class="empty">No notifications yet.</div>'?></div></section><script>
(function(){
  let stream=null;
  const qs=(id)=>document.getElementById(id);
  const setText=(id,text)=>{const el=qs(id);if(el)el.textContent=text;};
  async function sendLocation(lat,lng,accuracy=0,demo=false){
    try{
      const r=await fetch('/?api=location',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lat,lng,accuracy,demo})});
      const d=await r.json();
      if(!d.ok) throw new Error(d.message||'Location request failed');
      setText('geoStatus',String(d.status||'unknown').replace(/_/g,' '));
      setText('gpsText',d.message||'Location updated.');
      setText('coords',lat.toFixed(5)+', '+lng.toFixed(5)+' · '+Math.round(accuracy||0)+'m accuracy');
      setText('attStatus',String(d.attendance_status||'not_started').replace(/_/g,' '));
    }catch(e){ console.error(e); setText('gpsText','Location update failed: '+e.message); }
  }
  function simulate(mode){
    const w=<?=json_encode($w, JSON_UNESCAPED_SLASHES)?>;
    let p;
    if(mode==='inside') p=[Number(w.latitude),Number(w.longitude)];
    else if(mode==='remote') p=[17.401,78.477];
    else p=[Number(w.latitude)+0.02,Number(w.longitude)+0.02];
    sendLocation(p[0],p[1],5,true);
  }
  function startGPS(){
    if(!navigator.geolocation){setText('gpsText','Geolocation is unavailable in this browser.');return;}
    setText('gpsText','Requesting GPS permission…');
    navigator.geolocation.watchPosition(
      p=>sendLocation(p.coords.latitude,p.coords.longitude,p.coords.accuracy),
      e=>setText('gpsText','GPS permission needed. Use the demo buttons if unavailable. ('+e.message+')'),
      {enableHighAccuracy:true,maximumAge:5000,timeout:10000}
    );
  }
  async function openCamera(){
    const box=qs('cameraBox');
    if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia){setText('photoMsg','Camera is unavailable. Use HTTPS and allow camera access.');return;}
    box.style.display='block';
    try{
      stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});
      qs('video').srcObject=stream;
      setText('photoMsg','Camera ready — click Capture.');
    }catch(e){box.style.display='none';setText('photoMsg','Camera permission was blocked. Allow camera access and try again.');console.error(e);}
  }
  function closeCamera(){if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;qs('cameraBox').style.display='none';}
  async function capture(){
    const v=qs('video');
    if(!v.videoWidth){setText('photoMsg','Camera is not ready yet.');return;}
    const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);
    try{
      const fd=new FormData();fd.append('photo_data',c.toDataURL('image/jpeg',.78));
      const r=await fetch('/?api=save_photo',{method:'POST',body:fd});
      const d=await r.json();
      if(!d.ok) throw new Error(d.message||'Photo upload failed');
      qs('myPhoto').src=d.photo+'?'+Date.now();setText('photoMsg','✓ Identity photo updated.');closeCamera();
    }catch(e){setText('photoMsg','Photo upload failed: '+e.message);console.error(e);}
  }
  function bind(){
    qs('btnGPS')?.addEventListener('click',startGPS);
    qs('btnInside')?.addEventListener('click',()=>simulate('inside'));
    qs('btnOutside')?.addEventListener('click',()=>simulate('outside'));
    qs('btnRemote')?.addEventListener('click',()=>simulate('remote'));
    qs('btnCamera')?.addEventListener('click',openCamera);
    qs('btnCapture')?.addEventListener('click',capture);
    qs('btnCancelCamera')?.addEventListener('click',closeCamera);
  }
  bind();
})();
</script><?php footer();}
