if(isset($_GET['action'])){$a=$_GET['action'];if($a==='logout'){session_destroy();header('Location:/?page=login');exit;}if($a==='login'){ $s=db()->prepare('SELECT * FROM users WHERE email=? AND active=1');$s->execute([$_POST['email']??'']);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){$_SESSION['uid']=$u['id'];header('Location:/');exit;}header('Location:/?page=login&error=1');exit;}if($a==='signup'){try{$s=db()->prepare('INSERT INTO users(name,email,password,role,department,photo) VALUES(?,?,?,?,?,?)');$s->execute([$_POST['name'],$_POST['email'],password_hash($_POST['password'],PASSWORD_DEFAULT),'employee',$_POST['department'],'assets/avatar-default.svg']);$_SESSION['uid']=db()->lastInsertId();header('Location:/?page=employee');exit;}catch(Exception $e){header('Location:/?page=signup&error=1');exit;}}$u=need();if($a==='add_employee'&&$u['role']==='manager'){$s=db()->prepare('INSERT INTO users(name,email,password,role,department,photo) VALUES(?,?,?,?,?,?)');$s->execute([$_POST['name'],$_POST['email'],password_hash($_POST['password']?:'password',PASSWORD_DEFAULT),'employee',$_POST['department']?:'Field Operations','assets/avatar-default.svg']);header('Location:/?page=employees');exit;}if($a==='leave'){$s=db()->prepare('INSERT INTO leave_requests(user_id,type,start_date,end_date,reason) VALUES(?,?,?,?,?)');$s->execute([$u['id'],$_POST['type'],$_POST['start_date'],$_POST['end_date'],$_POST['reason']]);$man=db()->query("SELECT id FROM users WHERE role='manager' LIMIT 1")->fetch();db()->prepare('INSERT INTO notifications(user_id,title,message,type) VALUES(?,?,?,?)')->execute([$man['id'],'New leave request',$u['name'].' submitted a '.$_POST['type'].' request.','warning']);header('Location:/?page=leave');exit;}if($a==='leave_decide'&&$u['role']==='manager'){$s=db()->prepare('SELECT * FROM leave_requests WHERE id=?');$s->execute([$_POST['id']]);$r=$s->fetch();$status=$_POST['decision']==='approved'?'approved':'rejected';db()->prepare('UPDATE leave_requests SET status=?,manager_comment=? WHERE id=?')->execute([$status,'Reviewed by manager',$r['id']]);db()->prepare('INSERT INTO notifications(user_id,title,message,type) VALUES(?,?,?,?)')->execute([$r['user_id'],'Leave request '.ucfirst($status),'Your '.$r['type'].' request was '.$status.'.','info']);header('Location:/?page=leaveadmin');exit;}if($a==='workplace'&&$u['role']==='manager'){db()->prepare('UPDATE workplaces SET name=?,latitude=?,longitude=?,radius=?,shift_start=?,shift_end=? WHERE id=1')->execute([$_POST['name'],$_POST['latitude'],$_POST['longitude'],$_POST['radius'],$_POST['shift_start'],$_POST['shift_end']]);header('Location:/?page=workplace');exit;}}
if(isset($_GET['api'])){$api=$_GET['api'];$u=need();if($api==='dashboard'&&$u['role']==='manager'){$d=db();$emps=$d->query("SELECT u.id,u.name,u.photo,l.latitude,l.longitude,l.status,l.recorded_at FROM users u LEFT JOIN (SELECT l1.* FROM locations l1 JOIN (SELECT user_id,MAX(id) mid FROM locations GROUP BY user_id) x ON x.mid=l1.id) l ON l.user_id=u.id WHERE u.role='employee' AND u.active=1")->fetchAll();$alerts=[];foreach($emps as $e)if($e['status']==='outside')$alerts[]=['title'=>'Outside geofence','message'=>$e['name'].' is outside the designated workplace.','type'=>'danger'];$leaves=$d->query("SELECT l.*,u.name FROM leave_requests l JOIN users u ON u.id=l.user_id WHERE l.status='pending' ORDER BY l.id DESC")->fetchAll();jsonout(['employees'=>$emps,'alerts'=>$alerts,'leaves'=>$leaves]);}if($api==='location'&&$u['role']==='employee'){$body=json_decode(file_get_contents('php://input'),true)?:$_POST;$lat=(float)$body['lat'];$lng=(float)$body['lng'];$w=workplace();$meters=dist($lat,$lng,$w['latitude'],$w['longitude']);$remote=db()->prepare("SELECT COUNT(*) n FROM leave_requests WHERE user_id=? AND status='approved' AND type='remote' AND start_date<=? AND end_date>=?");$remote->execute([$u['id'],today(),today()]);$isRemote=empty($body['demo']) && $remote->fetch()['n']>0;$status=$isRemote?'approved_remote':($meters<=$w['radius']?'inside':'outside');db()->prepare('INSERT INTO locations(user_id,latitude,longitude,status,accuracy,recorded_at) VALUES(?,?,?,?,?,?)')->execute([$u['id'],$lat,$lng,$status,$body['accuracy']??0,date('Y-m-d H:i:s')]);$a=attendance($u['id']);$now=date('Y-m-d H:i:s');$inShift=date('H:i')>=$w['shift_start']&&date('H:i')<=$w['shift_end'];$msg='Location reported: '.ucwords(str_replace('_',' ',$status)).'.';if(($status==='inside'||$status==='approved_remote')&&$inShift&&empty($a)){db()->prepare('INSERT INTO attendances(user_id,date,punch_in,status,checkin_lat,checkin_lng) VALUES(?,?,?,?,?,?)')->execute([$u['id'],today(),$now,'present',$lat,$lng]);$msg='Automatic check-in completed.';}if($status==='outside'){if($a && empty($a['punch_out'])){$end=new DateTime(today().' '.$w['shift_end'].':00');$nowDt=new DateTime($now);$ot=max(0,(int)floor(($nowDt->getTimestamp()-$end->getTimestamp())/60));db()->prepare('UPDATE attendances SET punch_out=?,overtime_minutes=? WHERE id=?')->execute([$now,$ot,$a['id']]);}$man=db()->query('SELECT id FROM users WHERE role="manager" LIMIT 1')->fetch();if($man)db()->prepare('INSERT INTO notifications(user_id,title,message,type) VALUES(?,?,?,?)')->execute([$man['id'],'Geofence alert',$u['name'].' moved outside the designated workplace.','danger']);$msg='You are outside the geofence. Manager has been alerted.';}elseif($a && empty($a['punch_out']) && date('H:i')>$w['shift_end']){$end=new DateTime(today().' '.$w['shift_end'].':00');$nowDt=new DateTime($now);$ot=max(0,(int)floor(($nowDt->getTimestamp()-$end->getTimestamp())/60));db()->prepare('UPDATE attendances SET punch_out=?,overtime_minutes=? WHERE id=?')->execute([$now,$ot,$a['id']]);$msg='Shift ended. Automatic checkout recorded; overtime calculated.';}$a=attendance($u['id']);jsonout(['ok'=>true,'status'=>$status,'attendance_status'=>$a['status']??'not_started','message'=>$msg,'overtime_minutes'=>$a['overtime_minutes']??0]);}if($api==='save_photo'&&$u['role']==='employee'){$data=$_POST['photo_data']??'';if(!preg_match('#^data:image/jpeg;base64,#',$data))jsonout(['ok'=>false,'message'=>'Invalid camera image']);$raw=base64_decode(substr($data,strpos($data,',')+1));$name='uploads/user_'.$u['id'].'_'.time().'.jpg';$target=__DIR__.'/'.$name;if(!is_dir(dirname($target)))mkdir(dirname($target),0777,true);file_put_contents($target,$raw);db()->prepare('UPDATE users SET photo=? WHERE id=?')->execute([$name,$u['id']]);jsonout(['ok'=>true,'photo'=>'/'.$name]);}if($api==='csv'&&$u['role']==='manager'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename=dvps39-attendance.csv');$out=fopen('php://output','w');fputcsv($out,['Date','Employee','Department','Punch In','Punch Out','Status','Overtime Minutes']);$rows=db()->query("SELECT a.*,u.name,u.department FROM attendances a JOIN users u ON u.id=a.user_id ORDER BY a.date DESC")->fetchAll();foreach($rows as $r)fputcsv($out,[$r['date'],$r['name'],$r['department'],$r['punch_in'],$r['punch_out'],$r['status'],$r['overtime_minutes']]);exit;}}
